    const registrada = b.isExecuted && b.first().json.status === 'success';
    const d = r.data;
    return 'Cálculo: SL ' + d.sl_pts + ' pts · Contratos ' + d.contratos + ' · Riesgo USD ' + d.riesgo_usd + ' · R:R ' + d.rr + ' · TP correcto: ' + d.tp_correcto
