={
  "record_id": {{ JSON.stringify($('Memoria de sesión').first().json.record_id) }},
  "datos_clave": {{ JSON.stringify((() => {
    const prev = JSON.parse($('Memoria de sesión').first().json.datos_clave);
    const r = $('Registro de trazabilidad').first().json;
    return JSON.stringify({
      trader: prev.trader,
      cuenta: prev.cuenta,
      mensajes: (prev.mensajes || 0) + 1,
      operaciones_registradas: (prev.operaciones_registradas || 0) + (r.registrada === true ? 1 : 0),
      auditorias_rojas: (prev.auditorias_rojas ?? prev.rojas ?? 0) + (r.semaforo === 'Rojo' ? 1 : 0),
      escalamientos: (prev.escalamientos || 0) + (r.requiere_humano === true ? 1 : 0),
      ultima_categoria: r.categoria
    });
  })()) }}
}

